orchestrator_loop.pseudocode:
cycle = 0
while not shutdown_flag:
    cycle += 1
    try:
        for agent in agents:
            log(cycle, agent.name, 'start', '')
            result = agent.run(cycle, context)
            log(cycle, agent.name, 'success', f'output_keys={list(result.keys())}')
            context.update(result)
            log_file_changes(agent.name, result.get('changed_files', []))
        if hitl_due(cycle): hitl_pause(cycle, context)
    except (JSONDecodeError, TimeoutError, ValueError) as e:
        log(cycle, 'orchestrator', 'error', f'{type(e).__name__}: {e}')
        save_context_snapshot(cycle, context)
        if not retry_lightly(): break
    except Exception as e:
        log(cycle, 'orchestrator', 'fatal', f'{type(e).__name__}: {e}')
        save_context_snapshot(cycle, context)
        break
